window.QBANK={"1":[{"i":"REGOX-reg_property_transactions-001","t":"Under IRC §1012(a), the basis of property is generally its cost, except as otherwise provided in this subchapter and provisions relating to corporate distributions, partnerships, and capital gain/loss.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1012(a)","rat":"§1012(a) sets basis, as a general rule, at cost."},{"i":"REGOX-reg_property_transactions-002","t":"Under IRC §1012(b), a building's cost basis excludes real property taxes treated as imposed on the taxpayer under §164(d).","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1012(b)","rat":"§1012(b) excludes real property taxes treated as imposed on the taxpayer from that cost basis."},{"i":"REGOX-reg_property_transactions-003","t":"Under IRC §1016(a)(1), proper adjustment to basis must be made for expenditures, receipts, losses, or other items properly chargeable to a capital account.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1016(a)(1)","rat":"§1016(a)(1) provides for basis adjustments for items such as capital expenditures."},{"i":"REGOX-reg_property_transactions-004","t":"Under IRC §1016(a)(2), basis is reduced by depreciation allowed as a deduction in computing taxable income, but not below the amount that was allowable.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1016(a)(2)","rat":"This restates the allowed-or-allowable rule of §1016(a)(2) directly."},{"i":"REGOX-reg_property_transactions-005","t":"Under IRC §1016(a)(2), if the taxpayer did not adopt a depreciation method under §167, the allowable amount used for the basis adjustment is determined under the 200% declining balance method.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1016(a)(2)","rat":"If no depreciation method was adopted, the allowable amount is determined under the straight line method."},{"i":"REGOX-reg_property_transactions-006","t":"Under IRC §1016(a), the basis adjustment for capital expenditures can be skipped if the taxpayer elects not to claim a depreciation deduction.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1016(a)","rat":"§1016(a) requires proper adjustment \"in all cases\" — it is not optional."},{"i":"REGOX-reg_property_transactions-007","t":"Under IRC §1016(b), when a property's basis is a substituted basis, the adjustments under subsection (a) are made only after first making similar adjustments for the period the transferor, donor, or grantor held the property.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1016(b)","rat":"§1016(b) requires adjusting for the prior holding period first for a substituted basis."},{"i":"REGOX-reg_property_transactions-008","t":"Under IRC §1012(a), the basis of property purchased for business use is always its fair market value at acquisition, regardless of cost.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1012(a)","rat":"The basis under §1012(a) is cost, not fair market value."},{"i":"REGOX-reg_property_transactions-009","t":"Under IRC §1015(a), the basis of property acquired by gift after December 31, 1920, is generally the same as the donor's basis (a carryover basis).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1015(a)","rat":"§1015(a) sets the carryover basis rule for gifts — the donee generally takes the donor's basis."},{"i":"REGOX-reg_property_transactions-010","t":"Under IRC §1015(a), even where the donor's adjusted basis exceeds the property's fair market value at the time of the gift, the donee's basis for determining loss remains the donor's adjusted basis.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1015(a)","rat":"If the donor's basis exceeds fair market value, basis for determining loss is the fair market value at the time of the gift."},{"i":"REGOX-reg_property_transactions-011","t":"Under IRC §1014(a)(1), the basis of property acquired from a decedent is generally its fair market value as of the decedent's date of death.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1014(a)(1)","rat":"This restates the date-of-death fair market value rule of §1014(a)(1) directly."},{"i":"REGOX-reg_property_transactions-012","t":"Under IRC §1014(a)(2), if the executor elects the alternate valuation date under §2032, the basis of the inherited property is its value as of that alternate valuation date.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1014(a)(2)","rat":"Under §1014(a)(2), if the §2032 alternate valuation date is elected, that value becomes the basis."},{"i":"REGOX-reg_property_transactions-013","t":"Under IRC §1015(d)(1)(A), for gifts made after September 2, 1958, the donee's basis is increased by the full amount of gift tax paid, with no limitation whatsoever.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1015(d)(1)(A)","rat":"The increase cannot exceed the property's fair market value at the time of the gift."},{"i":"REGOX-reg_property_transactions-014","t":"Under IRC §1014(e), if property the decedent acquired by gift within one year of death passes back to the donor (or the donor's spouse), the donor's basis is the property's fair market value as of the decedent's date of death.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1014(e)(1)","rat":"Here the donor's basis is the decedent's adjusted basis immediately before death, not fair market value."},{"i":"REGOX-reg_property_transactions-015","t":"Under IRC §1014(b)(1), property acquired by bequest, devise, or inheritance, or property acquired from the decedent's estate, is treated as property acquired from the decedent for purposes of §1014(a).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1014(b)(1)","rat":"This restates the text of §1014(b)(1) directly."},{"i":"REGOX-reg_property_transactions-016","t":"Under IRC §1014(c), §1014 does not apply to property that constitutes a right to receive income in respect of a decedent under §691.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1014(c)","rat":"§1014(c) excludes IRD (income in respect of a decedent) assets from this rule."},{"i":"REGOX-reg_property_transactions-017","t":"Under IRC §1091(a), if substantially identical stock or securities are acquired during the period beginning 30 days before and ending 30 days after the sale of stock or securities, the loss deduction from that sale is disallowed.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(a)","rat":"This restates the wash sale loss disallowance rule of §1091(a) directly."},{"i":"REGOX-reg_property_transactions-018","t":"Under IRC §1091(a), the wash sale loss disallowance rule applies without exception even where a securities dealer realizes the loss in the ordinary course of business.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(a)","rat":"There is an exception: the wash sale rules do not apply to a loss realized by a dealer in the ordinary course of business."},{"i":"REGOX-reg_property_transactions-019","t":"The loss-disallowance period under IRC §1091(a) totals 61 days: 30 days before the sale, the day of the sale, and 30 days after the sale.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(a)","rat":"Counting \"30 days before the sale through 30 days after the sale\" totals 61 days."},{"i":"REGOX-reg_property_transactions-020","t":"Under IRC §1091(d), when a loss is disallowed, the basis of the newly acquired stock is the basis of the stock sold, increased or decreased by the difference between the purchase price of the new stock and the sale price of the stock sold.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(d)","rat":"This restates the basis computation for replacement stock under §1091(d) directly."},{"i":"REGOX-reg_property_transactions-021","t":"Under IRC §1091(e), a rule similar to subsection (a) applies to a loss realized on closing a short sale.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(e)","rat":"§1091(e) applies the wash sale rules by analogy to a loss on closing a short sale."},{"i":"REGOX-reg_property_transactions-022","t":"Under IRC §1091(a), the term \"stock or securities\" refers only to stock actually purchased and does not include a contract or option to acquire or sell stock.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(a)","rat":"The last sentence of §1091(a) also covers a contract or option to acquire or sell stock or securities."},{"i":"REGOX-reg_property_transactions-023","t":"Under IRC §1091(f), a contract or option to acquire stock that may be (or is) settled in cash is exempt from the wash sale rules for that reason alone.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(f)","rat":"§1091(f) provides that the mere possibility of cash settlement does not by itself take a transaction out of this section."},{"i":"REGOX-reg_property_transactions-024","t":"Under IRC §1091(b), when the quantity of stock or securities acquired is less than the quantity sold, the method for identifying which shares have a disallowed loss is determined under regulations prescribed by the Secretary.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(b)","rat":"This restates the text of §1091(b) directly."},{"i":"REGOX-reg_property_transactions-025","t":"Under IRC §248(a), if a corporation elects, it may deduct in the tax year it begins business the lesser of the amount of its organizational expenditures or $5,000 (reduced, but not below zero, by the amount by which the organizational expenditures exceed $50,000).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §248(a)(1)","rat":"This restates the immediate-deduction limit computation of §248(a)(1) directly."},{"i":"REGOX-reg_property_transactions-026","t":"Under IRC §248(a)(2), any remaining organizational expenditures not immediately deducted are amortized ratably over the 180-month period beginning with the month the corporation begins business.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §248(a)(2)","rat":"This restates the 180-month amortization rule of §248(a)(2)."},{"i":"REGOX-reg_property_transactions-027","t":"Under IRC §248(b), organizational expenditures means an expenditure that is incident to the creation of the corporation, chargeable to capital account, and of a character that, if the corporation had a limited life, would be amortized over that life.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §248(b)","rat":"This restates the definition of organizational expenditures in §248(b) directly."},{"i":"REGOX-reg_property_transactions-028","t":"Under IRC §248(c), the election to deduct organizational expenditures must be made no later than the time prescribed by law for filing the return for that tax year (including extensions).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §248(c)","rat":"This restates the election-deadline rule of §248(c)."},{"i":"REGOX-reg_property_transactions-029","t":"Under IRC §709(a), amounts paid to promote the sale of, or to sell, an interest in a partnership are generally deductible by the partnership or the partners.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §709(a)","rat":"§709(a) generally disallows a deduction for such expenditures."},{"i":"REGOX-reg_property_transactions-030","t":"Under IRC §709(b)(1), the election for a partnership's organizational expenses follows the same $5,000/$50,000 threshold and 180-month amortization structure as §248 for corporations.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §709(b)(1)","rat":"§709(b)(1) provides the same immediate-deduction-and-amortization structure as §248."},{"i":"REGOX-reg_property_transactions-031","t":"Under IRC §709(b)(3), a partnership's organizational expenses must be incident to the creation of the partnership, chargeable to capital account, and of a character that, if the partnership had a fixed life, would be amortized over that life.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §709(b)(3)","rat":"This restates the definition of organizational expenses in §709(b)(3)."},{"i":"REGOX-reg_property_transactions-032","t":"Under IRC §195(a), a taxpayer may deduct start-up expenditures in full, immediately, in the year the business begins, without making any separate election.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §195(a)","rat":"§195(a) generally disallows the deduction unless the election under (b) is made."},{"i":"REGOX-reg_property_transactions-033","t":"Under IRC §195(b)(1)(A), the amount of start-up expenditures immediately deductible in the tax year the active trade or business actually begins is the lesser of the expenditures or $5,000 (reduced, but not below zero, by the amount by which start-up expenditures exceed $50,000).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §195(b)(1)(A)","rat":"The immediate-deduction computation in §195(b)(1)(A) has the same structure as §248(a)(1)."},{"i":"REGOX-reg_property_transactions-034","t":"Under IRC §195(c)(1), \"start-up expenditures\" includes amounts paid to investigate the creation or acquisition of an active trade or business, but excludes amounts for which a deduction is allowable under §163(a), §164, §174, or §174A.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §195(c)(1)","rat":"This restates the definition of start-up expenditures and excluded items in §195(c)(1)."},{"i":"REGMC-reg_property_transactions-001","t":"Under IRC §1012(a), the basis of property is generally its cost, except as otherwise provided in the Internal Revenue Code provisions relating to which of the following?","c":"A","mc":{"s":"Under IRC §1012(a), the basis of property is generally its cost, except as otherwise provided in the Internal Revenue Code provisions relating to which of the following?","d":"","o":["Corporate distributions and adjustments (Subchapter C), partners and partnerships (Subchapter K), and capital gains and losses (Subchapter P)","S corporation elections only","Real property transactions only","No exceptions exist; §1012 basis is never subject to any other Code provision"],"a":1,"cite":"26 U.S.C. §1012(a)","rat":"§1012(a) states exceptions to the cost-basis rule for corporate distributions, partnerships, and capital gain/loss provisions."}},{"i":"REGMC-reg_property_transactions-002","t":"A business properly claims depreciation deductions under §167 on a machine it purchased for use in its trade. Under IRC §1016(a)(2), when the machine is later sold, its basis must be reduced by an amount equal to the depreciation deductions actually allowed in computing taxable income, subject to what floor?","c":"A","mc":{"s":"A business properly claims depreciation deductions under §167 on a machine it purchased for use in its trade. Under IRC §1016(a)(2), when the machine is later sold, its basis must be reduced by an amount equal to the depreciation deductions actually allowed in computing taxable income, subject to what floor?","d":"","o":["The floor is zero; basis can never be reduced below zero, and allowed depreciation is always used regardless of what was allowable","The reduction may not be less than the amount allowable, even if the taxpayer claimed less than the amount allowable","The reduction is always exactly the amount claimed on the tax return, with no minimum","No reduction is required, since depreciation is treated as a wholly separate item unrelated to basis"],"a":2,"cite":"26 U.S.C. §1016(a)(2)","rat":"§1016(a)(2) requires reducing basis by at least the allowable amount whenever the amount actually allowed is less than the allowable amount (the allowed-or-allowable rule)."}},{"i":"REGMC-reg_property_transactions-003","t":"A taxpayer purchases real property, and a portion of the purchase price is treated under §164(d) as real property taxes imposed on the taxpayer. Under IRC §1012(b), how is this amount treated for purposes of computing the basis of the real property?","c":"A","mc":{"s":"A taxpayer purchases real property, and a portion of the purchase price is treated under §164(d) as real property taxes imposed on the taxpayer. Under IRC §1012(b), how is this amount treated for purposes of computing the basis of the real property?","d":"","o":["It is included in the cost basis of the real property","It is excluded from the cost basis of the real property","It is capitalized as a separate 15-year intangible asset","It permanently increases the basis of the property by twice the amount"],"a":2,"cite":"26 U.S.C. §1012(b)","rat":"§1012(b) excludes from a building's cost basis any real property taxes treated as imposed on the taxpayer under §164(d)."}},{"i":"REGMC-reg_property_transactions-004","t":"An individual receives stock as a gift. The donor's adjusted basis in the stock was $30,000, and the fair market value of the stock on the date of the gift was $20,000. The donee later sells the stock for $15,000, resulting in a loss. Under IRC §1015(a), what basis must the donee use to determine the amount of the loss?","c":"A","mc":{"s":"An individual receives stock as a gift. The donor's adjusted basis in the stock was $30,000, and the fair market value of the stock on the date of the gift was $20,000. The donee later sells the stock for $15,000, resulting in a loss. Under IRC §1015(a), what basis must the donee use to determine the amount of the loss?","d":"","o":["$30,000 (the donor's adjusted basis)","$20,000 (the fair market value at the date of the gift)","$15,000 (the amount realized on the sale)","$25,000 (the average of the donor's basis and the fair market value)"],"a":2,"cite":"26 U.S.C. §1015(a)","rat":"If the donor's basis exceeds fair market value at the time of the gift, basis for determining loss is the fair market value at the time of the gift."}},{"i":"REGMC-reg_property_transactions-005","t":"Which of the following is NOT one of the bases specified in IRC §1014(a) for property acquired from a decedent?","c":"A","mc":{"s":"Which of the following is NOT one of the bases specified in IRC §1014(a) for property acquired from a decedent?","d":"","o":["Fair market value of the property at the date of the decedent's death","Value at the applicable valuation date under §2032, if the executor elected alternate valuation","Value determined under §2032A, if that section's election applies","The decedent's original cost basis, increased by a cost-of-living adjustment"],"a":4,"cite":"26 U.S.C. §1014(a)","rat":"§1014(a)(1)-(4) list the decedent's basis for date-of-death value, §2032 alternate valuation date value, §2032A value, and the §2031(c) exclusion election — there is no inflation-indexed cost basis rule."}},{"i":"REGMC-reg_property_transactions-006","t":"A donor gives appreciated property to a decedent 8 months before the decedent's death. Upon the decedent's death, the property passes back to the original donor. Under IRC §1014(e), what is the donor's basis in the property immediately after acquiring it from the decedent?","c":"A","mc":{"s":"A donor gives appreciated property to a decedent 8 months before the decedent's death. Upon the decedent's death, the property passes back to the original donor. Under IRC §1014(e), what is the donor's basis in the property immediately after acquiring it from the decedent?","d":"","o":["The fair market value of the property at the date of the decedent's death","The decedent's adjusted basis in the property immediately before the decedent's death","The donor's original basis in the property before making the gift","Zero, because the property was gifted shortly before death"],"a":2,"cite":"26 U.S.C. §1014(e)(1)","rat":"If property given within one year of death reverts to the original donor, that donor's basis is the decedent's adjusted basis immediately before death, not a step-up to date-of-death value."}},{"i":"REGMC-reg_property_transactions-007","t":"On November 1, an investor sells 100 shares of XYZ stock at a loss. On November 20 of the same year, the investor purchases 100 shares of substantially identical XYZ stock. The investor is not a dealer in securities. Under IRC §1091(a), how is the loss treated?","c":"A","mc":{"s":"On November 1, an investor sells 100 shares of XYZ stock at a loss. On November 20 of the same year, the investor purchases 100 shares of substantially identical XYZ stock. The investor is not a dealer in securities. Under IRC §1091(a), how is the loss treated?","d":"","o":["It is fully deductible because the purchase was a separate, unrelated transaction","It is disallowed because the purchase occurred within 30 days after the sale","It is disallowed only if the investor also sold short the same stock","Half of the loss is disallowed and half is deductible"],"a":2,"cite":"26 U.S.C. §1091(a)","rat":"Because substantially identical securities were purchased within 30 days after the sale, the loss is disallowed under the wash sale rules."}},{"i":"REGMC-reg_property_transactions-008","t":"Under IRC §1091(d), when a loss on the sale of stock is disallowed under the wash sale rules, the basis of the replacement stock acquired is determined as:","c":"A","mc":{"s":"Under IRC §1091(d), when a loss on the sale of stock is disallowed under the wash sale rules, the basis of the replacement stock acquired is determined as:","d":"","o":["The fair market value of the replacement stock on the date it was acquired","The basis of the stock sold, increased or decreased by the difference between the price paid for the replacement stock and the price at which the original stock was sold","Zero, because the loss was disallowed","The purchase price of the replacement stock only, with no reference to the stock sold"],"a":2,"cite":"26 U.S.C. §1091(d)","rat":"§1091(d) computes the replacement stock's basis by adjusting the basis of the stock sold for the difference between the purchase price and the sale price."}},{"i":"REGMC-reg_property_transactions-009","t":"Under the exception stated in IRC §1091(a), which taxpayer may deduct a loss realized on a sale of stock followed by the purchase of substantially identical stock within the wash sale window?","c":"A","mc":{"s":"Under the exception stated in IRC §1091(a), which taxpayer may deduct a loss realized on a sale of stock followed by the purchase of substantially identical stock within the wash sale window?","d":"","o":["An individual investor holding the stock for personal investment purposes","A dealer in stock or securities, if the loss is sustained in a transaction made in the ordinary course of that business","A corporation selling stock to an unrelated third party in a one-time transaction","Any taxpayer, because the wash sale rule contains no exceptions"],"a":2,"cite":"26 U.S.C. §1091(a)","rat":"§1091(a) excludes only losses realized by a dealer in the ordinary course of business from the wash sale rules."}},{"i":"REGMC-reg_property_transactions-010","t":"A newly formed corporation incurs $3,000 of organizational expenditures (as defined in §248(b)) and begins business in July of Year 1. Assuming a proper election under IRC §248(a), what is the corporation's deduction for organizational expenditures in Year 1?","c":"A","mc":{"s":"A newly formed corporation incurs $3,000 of organizational expenditures (as defined in §248(b)) and begins business in July of Year 1. Assuming a proper election under IRC §248(a), what is the corporation's deduction for organizational expenditures in Year 1?","d":"","o":["$3,000, fully deductible because it does not exceed $5,000","$5,000, the statutory dollar amount","$1,000, with the remainder permanently capitalized","$0, because organizational expenditures may never be deducted"],"a":1,"cite":"26 U.S.C. §248(a)(1)","rat":"Because the expenditure is under $5,000 and there is no phase-out from exceeding $50,000, the full $3,000 is deductible in the year the business begins."}},{"i":"REGMC-reg_property_transactions-011","t":"A partnership incurs $60,000 of organizational expenses (as defined in §709(b)(3)) and properly elects under IRC §709(b) in the year it begins business. Under §709(b)(1)(A), what is the maximum amount immediately deductible in that year?","c":"A","mc":{"s":"A partnership incurs $60,000 of organizational expenses (as defined in §709(b)(3)) and properly elects under IRC §709(b) in the year it begins business. Under §709(b)(1)(A), what is the maximum amount immediately deductible in that year?","d":"","o":["$5,000","$0","$10,000","$50,000"],"a":2,"cite":"26 U.S.C. §709(b)(1)(A)","rat":"The $5,000 limit is reduced by the $10,000 excess over $50,000 (not below zero), bringing the immediate-deduction limit to $0, so the immediate deduction is $0."}},{"i":"REGMC-reg_property_transactions-012","t":"A taxpayer incurs $52,000 of start-up expenditures (as defined in §195(c)(1)) before actively beginning a new trade or business. Under IRC §195(b)(1)(A), what is the maximum amount currently deductible in the taxable year the active trade or business begins (before considering ratable amortization of any remainder)?","c":"A","mc":{"s":"A taxpayer incurs $52,000 of start-up expenditures (as defined in §195(c)(1)) before actively beginning a new trade or business. Under IRC §195(b)(1)(A), what is the maximum amount currently deductible in the taxable year the active trade or business begins (before considering ratable amortization of any remainder)?","d":"","o":["$5,000","$3,000","$50,000","$52,000"],"a":2,"cite":"26 U.S.C. §195(b)(1)(A)","rat":"The $5,000 limit is reduced by the $2,000 excess over $50,000, bringing the immediate-deduction limit to $3,000, which is less than the actual expenditure ($52,000), so the immediate deduction is $3,000."}}],"2":[{"i":"REGOX-reg_property_transactions-035","t":"Under IRC §168(a), the depreciation deduction for tangible property is determined using the applicable depreciation method, the applicable recovery period, and the applicable convention.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(a)","rat":"This restates the three MACRS components of §168(a) directly."},{"i":"REGOX-reg_property_transactions-036","t":"Under IRC §168(b)(3), nonresidential real property and residential rental property must use the straight line method.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(b)(3)(A)(B)","rat":"§168(b)(3) requires the straight line method for real property."},{"i":"REGOX-reg_property_transactions-037","t":"Under IRC §168(c), the applicable recovery period for residential rental property is 39 years.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(c)","rat":"Residential rental property has a 27.5-year recovery period; 39 years is for nonresidential real property."},{"i":"REGOX-reg_property_transactions-038","t":"Under IRC §168(d)(1), except as otherwise provided in this subsection, the applicable convention is the half-year convention.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(d)(1)","rat":"This restates the half-year convention rule of §168(d)(1)."},{"i":"REGOX-reg_property_transactions-039","t":"Under IRC §168(d)(2), nonresidential real property, residential rental property, and railroad grading or tunnel bores use the mid-month convention.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(d)(2)","rat":"This restates the mid-month convention for real property under §168(d)(2)."},{"i":"REGOX-reg_property_transactions-040","t":"Under IRC §168(d)(3)(A), if the aggregate basis of property placed in service during the last 3 months of the tax year exceeds 40% of the aggregate basis of all property placed in service during that year, the mid-quarter convention applies to all such property placed in service that year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(d)(3)(A)","rat":"This restates the 40% test of §168(d)(3)(A) directly."},{"i":"REGOX-reg_property_transactions-041","t":"Under IRC §168(b)(4), when computing MACRS depreciation, salvage value is subtracted from the depreciable basis based on the property's actual expected salvage value.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(b)(4)","rat":"§168(b)(4) requires treating salvage value as zero."},{"i":"REGOX-reg_property_transactions-042","t":"Under IRC §168(e)(1), property with a class life of more than 4 but less than 10 years is classified as 5-year property.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(e)(1)","rat":"This restates the 5-year property class listed in the §168(e)(1) table."},{"i":"REGOX-reg_property_transactions-043","t":"Under IRC §168(g)(2)(A), the alternative depreciation system computes depreciation using the 200% declining balance method.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(g)(2)(A)","rat":"The alternative depreciation system uses the straight line method without regard to salvage value."},{"i":"REGOX-reg_property_transactions-044","t":"Under IRC §168(d)(4)(A), the half-year convention treats all property placed in service (or disposed of) during a tax year as placed in service (or disposed of) at the midpoint of that tax year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(d)(4)(A)","rat":"This restates the half-year convention definition of §168(d)(4)(A) directly."},{"i":"REGOX-reg_property_transactions-045","t":"Under IRC §168(k)(1)(A), the depreciation deduction for the tax year qualified property is placed in service includes a special allowance equal to 100% of the property's adjusted basis.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(k)(1)(A)","rat":"This restates the 100% bonus depreciation rule of §168(k)(1)(A)."},{"i":"REGOX-reg_property_transactions-046","t":"Under IRC §168(k)(2)(A), one category of property that can qualify for bonus depreciation is property to which §168 applies with a recovery period of 20 years or less.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(k)(2)(A)(i)(I)","rat":"This restates the 20-years-or-less recovery period requirement of §168(k)(2)(A)(i)(I)."},{"i":"REGOX-reg_property_transactions-047","t":"Under IRC §168(k)(2)(A)(ii), to qualify for bonus depreciation, the property's original use must begin with the taxpayer, and there is no exception to this requirement whatsoever.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(k)(2)(A)(ii)","rat":"This provision has an exception: besides the original-use requirement, property acquired that meets the acquisition requirement of (E)(i) can also qualify."},{"i":"REGOX-reg_property_transactions-048","t":"Under IRC §168(k)(7), a taxpayer may elect out of bonus depreciation for a class of property placed in service during the tax year, and that election may be revoked only with the Secretary's consent.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(k)(7)","rat":"This restates the election-out and revocation-limit rule of §168(k)(7)."},{"i":"REGOX-reg_property_transactions-049","t":"Under IRC §168(k)(2)(D), property required to be depreciated under the alternative depreciation system (subsection (g)) is also included among bonus-depreciation qualified property.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(k)(2)(D)","rat":"§168(k)(2)(D) excludes property required to be depreciated under the alternative depreciation system from qualified property."},{"i":"REGOX-reg_property_transactions-050","t":"Under IRC §179(a), a taxpayer may elect to treat the cost of §179 property as an expense not chargeable to capital account, allowed as a deduction for the tax year the property is placed in service.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §179(a)","rat":"This restates the §179 immediate-expensing election rule."},{"i":"REGOX-reg_property_transactions-051","t":"Under IRC §179(d)(1)(C), to be §179 property, the property must be acquired by purchase for use in an active trade or business.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §179(d)(1)(C)","rat":"This restates the purchase and active-business-use requirements of §179(d)(1)(C)."},{"i":"REGOX-reg_property_transactions-052","t":"Under IRC §179(b)(3)(A), the amount allowed as a §179 deduction for a tax year cannot exceed the taxpayer's aggregate taxable income from the active conduct of a trade or business for that year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §179(b)(3)(A)","rat":"This restates the taxable-income limitation of §179(b)(3)(A)."},{"i":"REGOX-reg_property_transactions-053","t":"Under IRC §179(d)(4), the §179 deduction applies equally to individuals and corporations as well as to estates and trusts.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §179(d)(4)","rat":"§179(d)(4) provides that this section does not apply to estates and trusts."},{"i":"REGOX-reg_property_transactions-054","t":"Under IRC §179(b)(2), the §179 dollar limitation is reduced, dollar for dollar, by the amount by which the cost of §179 property placed in service during the tax year exceeds the statutory threshold amount.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §179(b)(2)","rat":"This restates the phase-out mechanism of §179(b)(2) without specifying the dollar amounts."},{"i":"REGOX-reg_property_transactions-055","t":"Under IRC §197(a), the adjusted basis of an amortizable §197 intangible is amortized ratably over 15 years, beginning with the month the intangible is acquired.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(a)","rat":"This restates the 15-year straight-line amortization rule of §197(a)."},{"i":"REGOX-reg_property_transactions-056","t":"Under IRC §197(d)(1), both goodwill and going concern value are included in the definition of a \"§197 intangible.\"","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(d)(1)(A)(B)","rat":"This restates the listing of goodwill and going concern value in §197(d)(1)(A),(B)."},{"i":"REGOX-reg_property_transactions-057","t":"Under IRC §197(c)(2), a self-created intangible that does not fall within (d)(1)(D), (E), or (F) generally qualifies as an amortizable §197 intangible even though it was not acquired from another person.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(c)(2)","rat":"§197(c)(2) excludes such self-created intangibles from amortizable §197 intangibles, except when created in connection with a business acquisition."},{"i":"REGOX-reg_property_transactions-058","t":"Under IRC §197(e)(2), an interest in land is excluded from the definition of a \"§197 intangible.\"","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(e)(2)","rat":"This restates the exclusion of land in §197(e)(2)."},{"i":"REGOX-reg_property_transactions-059","t":"Under IRC §197(e)(5)(A), an interest under an existing lease of tangible property is treated as a §197 intangible amortizable over 15 years.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(e)(5)(A)","rat":"§197(e)(5)(A) excludes an interest under an existing lease from the definition of a §197 intangible."},{"i":"REGOX-reg_property_transactions-060","t":"Under IRC §197(b), a taxpayer may claim a separate depreciation or amortization deduction on the same amortizable §197 intangible in addition to the 15-year amortization deduction under subsection (a).","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(b)","rat":"§197(b) allows no depreciation or amortization deduction other than as provided in subsection (a)."},{"i":"REGOX-reg_property_transactions-061","t":"Under IRC §197(d)(1)(E), a covenant not to compete entered into in connection with acquiring an interest in a trade or business (or a substantial part of one) is included among §197 intangibles.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(d)(1)(E)","rat":"This restates the inclusion of covenants not to compete in §197(d)(1)(E)."},{"i":"REGOX-reg_property_transactions-062","t":"Under IRC §197(f)(4)(B), the renewal of a franchise, trademark, or trade name (or a license, permit, etc. under (d)(1)(D)) is treated as a new acquisition for costs incurred in connection with that renewal.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(f)(4)(B)","rat":"This restates the rule treating a renewal as an acquisition under §197(f)(4)(B)."},{"i":"REGOX-reg_property_transactions-063","t":"Under IRC §197(e)(3)(A)(i), computer software that is readily available for purchase by the general public, subject to a nonexclusive license, and has not been substantially modified is excluded from the definition of a \"§197 intangible.\"","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(e)(3)(A)(i)","rat":"This restates the off-the-shelf computer software exclusion of §197(e)(3)(A)(i)."},{"i":"REGOX-reg_property_transactions-064","t":"Under IRC §197(f)(1)(A), when a taxpayer disposes of one of several amortizable §197 intangibles acquired in a single transaction (or series of related transactions) while retaining the others, a loss may be recognized on that disposition.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §197(f)(1)(A)","rat":"§197(f)(1)(A) provides that in this case no loss is recognized; instead, the basis of the retained intangibles is adjusted."},{"i":"REGMC-reg_property_transactions-013","t":"A calendar-year taxpayer places all of its 5-year MACRS property in service throughout the year, and the aggregate basis of property placed in service during the last 3 months of the year does not exceed 40 percent of the aggregate basis of all such property placed in service during the year. Under IRC §168(d)(1)-(3), what convention applies to this property?","c":"A","mc":{"s":"A calendar-year taxpayer places all of its 5-year MACRS property in service throughout the year, and the aggregate basis of property placed in service during the last 3 months of the year does not exceed 40 percent of the aggregate basis of all such property placed in service during the year. Under IRC §168(d)(1)-(3), what convention applies to this property?","d":"","o":["Mid-quarter convention","Mid-month convention","Half-year convention","Full-year convention"],"a":3,"cite":"26 U.S.C. §168(d)(1)","rat":"Because the 40% test is not met, the general half-year convention applies rather than the mid-quarter convention."}},{"i":"REGMC-reg_property_transactions-014","t":"A calendar-year taxpayer places $120,000 of §168 property in service during the year, of which $55,000 (about 46 percent) is placed in service during the last 3 months of the taxable year. Under IRC §168(d)(3)(A), which convention must be used for all such property placed in service during that year?","c":"A","mc":{"s":"A calendar-year taxpayer places $120,000 of §168 property in service during the year, of which $55,000 (about 46 percent) is placed in service during the last 3 months of the taxable year. Under IRC §168(d)(3)(A), which convention must be used for all such property placed in service during that year?","d":"","o":["Half-year convention","Mid-month convention","Mid-quarter convention","Mid-year convention"],"a":3,"cite":"26 U.S.C. §168(d)(3)(A)","rat":"Because the last three months' acquisitions exceed 40% (46%) of the total, the mid-quarter convention applies to all such property placed in service that year."}},{"i":"REGMC-reg_property_transactions-015","t":"Under IRC §168(c), what is the applicable recovery period for nonresidential real property?","c":"A","mc":{"s":"Under IRC §168(c), what is the applicable recovery period for nonresidential real property?","d":"","o":["15 years","27.5 years","39 years","20 years"],"a":3,"cite":"26 U.S.C. §168(c)","rat":"Nonresidential real property has a 39-year recovery period (residential rental property is 27.5 years)."}},{"i":"REGMC-reg_property_transactions-016","t":"A piece of equipment has a class life of 22 years for purposes of §168(e)(1). Under the classification table in that subsection, this property is treated as:","c":"A","mc":{"s":"A piece of equipment has a class life of 22 years for purposes of §168(e)(1). Under the classification table in that subsection, this property is treated as:","d":"","o":["10-year property","15-year property","20-year property","7-year property"],"a":2,"cite":"26 U.S.C. §168(e)(1)","rat":"Property with a class life of 20 years or more but less than 25 years is classified as 15-year property."}},{"i":"REGMC-reg_property_transactions-017","t":"Which of the following properties would, by itself, satisfy the recovery-period component of the definition of 'qualified property' under IRC §168(k)(2)(A)(i)(I) for the additional first-year (bonus) depreciation allowance?","c":"A","mc":{"s":"Which of the following properties would, by itself, satisfy the recovery-period component of the definition of 'qualified property' under IRC §168(k)(2)(A)(i)(I) for the additional first-year (bonus) depreciation allowance?","d":"","o":["Nonresidential real property with a 39-year recovery period","Residential rental property with a 27.5-year recovery period","Section 168 property with a 7-year recovery period","Property with a recovery period of 25 years or more"],"a":3,"cite":"26 U.S.C. §168(k)(2)(A)(i)(I)","rat":"§168(k)(2)(A)(i)(I) lists §168 property with a recovery period of 20 years or less as one qualifying category, which includes 7-year property."}},{"i":"REGMC-reg_property_transactions-018","t":"Under IRC §179(d)(2), which of the following acquisitions of property would NOT qualify as a 'purchase' for purposes of the §179 election?","c":"A","mc":{"s":"Under IRC §179(d)(2), which of the following acquisitions of property would NOT qualify as a 'purchase' for purposes of the §179 election?","d":"","o":["Property bought for cash from an unrelated third-party vendor","Property acquired from a person whose relationship to the acquirer would result in disallowance of losses under §267","Property purchased on credit from an unrelated dealer","Property purchased at a public auction from an unrelated seller"],"a":2,"cite":"26 U.S.C. §179(d)(2)(A)","rat":"Property acquired from a related party whose loss would be disallowed under §267 does not qualify as a \"purchase\" for §179 purposes."}},{"i":"REGMC-reg_property_transactions-019","t":"A calendar-year corporation places $30,000 of section 179 property in service and has $18,000 of taxable income derived from the active conduct of its trade or business (computed without regard to the §179 deduction) for the year. Under IRC §179(b)(3)(A), what is the maximum §179 deduction allowed for the year, before considering any carryover of a prior disallowed amount?","c":"A","mc":{"s":"A calendar-year corporation places $30,000 of section 179 property in service and has $18,000 of taxable income derived from the active conduct of its trade or business (computed without regard to the §179 deduction) for the year. Under IRC §179(b)(3)(A), what is the maximum §179 deduction allowed for the year, before considering any carryover of a prior disallowed amount?","d":"","o":["$30,000","$18,000","$12,000","$0"],"a":2,"cite":"26 U.S.C. §179(b)(3)(A)","rat":"The §179 deduction cannot exceed the taxpayer's aggregate active trade or business taxable income for the year, so it is limited to $18,000."}},{"i":"REGMC-reg_property_transactions-020","t":"A corporation acquires an active trade or business, including goodwill valued at $200,000, in a taxable acquisition. Under IRC §197(a), over what period is this goodwill amortized?","c":"A","mc":{"s":"A corporation acquires an active trade or business, including goodwill valued at $200,000, in a taxable acquisition. Under IRC §197(a), over what period is this goodwill amortized?","d":"","o":["5 years","15 years","20 years","39 years"],"a":2,"cite":"26 U.S.C. §197(a)","rat":"Goodwill, an amortizable §197 intangible, is amortized ratably over 15 years beginning with the month of acquisition."}},{"i":"REGMC-reg_property_transactions-021","t":"Which of the following is specifically excluded from the definition of 'section 197 intangible' under IRC §197(e)?","c":"A","mc":{"s":"Which of the following is specifically excluded from the definition of 'section 197 intangible' under IRC §197(e)?","d":"","o":["Goodwill acquired in the purchase of a trade or business","A covenant not to compete entered into in connection with the acquisition of a trade or business","An interest in land","A franchise acquired in connection with the acquisition of a trade or business"],"a":3,"cite":"26 U.S.C. §197(e)(2)","rat":"§197(e)(2) expressly excludes an interest in land from the definition of a §197 intangible."}},{"i":"REGMC-reg_property_transactions-022","t":"A taxpayer internally develops (self-creates) a customer list at a cost of $10,000, not in connection with the acquisition of a trade or business or substantial portion thereof. Under IRC §197(c)(2), how is this self-created intangible treated?","c":"A","mc":{"s":"A taxpayer internally develops (self-creates) a customer list at a cost of $10,000, not in connection with the acquisition of a trade or business or substantial portion thereof. Under IRC §197(c)(2), how is this self-created intangible treated?","d":"","o":["It is an amortizable section 197 intangible eligible for 15-year amortization","It is not an amortizable section 197 intangible, because it was created by the taxpayer rather than acquired","It is immediately deductible in the year it is created","It is amortized over 5 years under §197"],"a":2,"cite":"26 U.S.C. §197(c)(2)","rat":"A self-created intangible is excluded from amortizable §197 intangibles unless created in connection with a business acquisition, except as described in (d)(1)(D), (E), or (F)."}}]};
window.PAIRS=[{"n":1,"s":0.404,"o":{"i":"REGOX-reg_property_transactions-011","t":"Under IRC §1014(a)(1), the basis of property acquired from a decedent is generally its fair market value as of the decedent's date of death.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_property_transactions-014","t":"Under IRC §1014(e), if property the decedent acquired by gift within one year of death passes back to the donor (or the donor's spouse), the donor's basis is the property's fair market value as of the decedent's date of death.","y":null,"e":"US CPA REG"}},{"n":2,"s":0.336,"o":{"i":"REGOX-reg_property_transactions-035","t":"Under IRC §168(a), the depreciation deduction for tangible property is determined using the applicable depreciation method, the applicable recovery period, and the applicable convention.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_property_transactions-037","t":"Under IRC §168(c), the applicable recovery period for residential rental property is 39 years.","y":null,"e":"US CPA REG"}}];
